local a=require("fcs.io.hwconfig")local b=require("fcs.io.tuningdefaults")local c={FILES={devbind="eh2_devbind.tbl",senscal="eh2_senscal.tbl",tuning="eh2_tuning.tbl",fuelcal="eh2_fuelcal.tbl"}}function c.defaults(d)local e=a.defaults()if d=="devbind"then return{thrusters=e.thrusters,sensors=e.sensors,fuelRelay=e.fuelRelay}end;if d=="senscal"then return e.bindings end;if d=="tuning"then return b.get()end;if d=="fuelcal"then return{fuel=require("fcs.fueltable").default}end;error("unknown cfg kind: "..tostring(d))end;function c.merge(d,f)f=f or{}if d=="senscal"and type(f)=="table"and f.signHeading~=nil and f.compassSign==nil then local g={}for h,i in pairs(f)do g[h]=i end;g.compassSign=f.signHeading;f=g end;return a.merge(f,c.defaults(d))end;function c.validate(d,j)if type(j)~="table"then return false,"not a table"end;local k=({devbind={"thrusters","sensors"},senscal={"signPitch","signHeading"},tuning={"gains","caps","feel"},fuelcal={"fuel"}})[d]for l,h in ipairs(k or{})do if j[h]==nil then return false,"missing "..h end end;return true end;function c.load(d,m)local n=m(c.FILES[d])if n==nil then return c.merge(d,{}),false,nil end;local f=textutils.unserialise(n)if type(f)~="table"then return c.merge(d,{}),true,"unparseable"end;return c.merge(d,f),true,nil end;function c.sessionFile(d)local o=c.FILES[d]if not o then return nil end;return o:gsub("%.tbl$",".session.tbl")end;function c.loadLive(d,m)local p=c.sessionFile(d)if p then local n=m(p)if n~=nil then local f=textutils.unserialise(n)if type(f)=="table"then return c.merge(d,f),true,nil end end end;return c.load(d,m)end;function c.save(d,j,q)return q(c.FILES[d],textutils.serialise(j))end;function c.splitLegacy(r)return{devbind={thrusters=r.thrusters,sensors=r.sensors,fuelRelay=r.fuelRelay},senscal=r.bindings}end;function c.assembleHw(s,t)return{thrusters=s.thrusters,sensors=s.sensors,fuelRelay=s.fuelRelay,bindings=t}end;function c.tryAssemble(m)local u,v,w=c.loadLive("devbind",m)local x,y,z=c.loadLive("senscal",m)if w